def is_prime(n):
    if n <= 1:
        return False
    i = 2
    while i < n:
        if n % i == 0:
            return False
        i = i + 1
    return True

pr.starter:
def hcf(a, b):
    pass

def lcm(a, b):
    pass

pr.solution:
def hcf(a, b):
    h = 1
    i = 1
    while i <= a and i <= b:
        if a % i == 0 and b % i == 0:
            h = i
        i = i + 1
    return h

def lcm(a, b):
    l = max(a, b)
    while not (l % a == 0 and l % b == 0):
        l = l + 1
    return l

def stats(num, bound):
    total = 0
    largest = num[0]
    smallest = num[0]
    count = 0
    for i in range(0, len(num)):
        total = total + num[i]
        if num[i] > largest:
            largest = num[i]
        if num[i] < smallest:
            smallest = num[i]
        if num[i] > bound:
            count = count + 1
    return [total, largest, smallest, count]

pr.starter:
def delete_at(num, P):
    pass

def insert_at(num, P, x):
    pass

pr.solution:
def delete_at(num, P):
    N = len(num)
    for i in range(P, N - 1):
        num[i] = num[i + 1]
    num[N - 1] = 0
    return num

def insert_at(num, P, x):
    num = num + [0]
    N = len(num)
    for i in range(N - 1, P, -1):
        num[i] = num[i - 1]
    num[P] = x
    return num

pr.starter:
def find_first(s, ch):
    pass

def quotes_ok(s):
    pass

pr.solution:
def find_first(s, ch):
    index = -1
    i = 0
    found = False
    while i < len(s) and not found:
        if s[i] == ch:
            index = i
            found = True
        i = i + 1
    return index

def quotes_ok(s):
    pair = 0
    for i in range(0, len(s)):
        if s[i] == "\"":
            pair = pair + 1
    return pair % 2 == 0

