pr.solution:
def average(marks):
    if len(marks) == 0:
        return 0
    total = 0
    for i in range(0, len(marks)):
        total = total + marks[i]
    return total / len(marks)

def to_binary4(D):
    if D < 0 or D > 15:
        return "Overflow"
    B = [0, 0, 0, 0]
    i = 0
    while D > 0:
        B[3 - i] = D % 2
        D = D // 2
        i = i + 1
    return B

