def tri(a, b, c):
    if a <= 0 or b <= 0 or c <= 0:
        return 'Cannot form a triangle'
    elif a + b <= c or a + c <= b or b + c <= a:
        return 'Cannot form a triangle'
    else:
        if a == b and a == c:
            return 'equilateral'
        elif a == b or a == c or b == c:
            return 'isosceles'
        else:
            return 'scalene'
