def run(size, ops):
    q = [None] * size
    first = 0
    N = 0
    result = []
    for op in ops:
        if op[0] == 'add':
            if N == size:
                result.append('Full')
            else:
                q[(first + N) % size] = op[1]
                N += 1
        else:
            if N == 0:
                result.append('Empty')
            else:
                result.append(q[first])
                first = (first + 1) % size
                N -= 1
    return result

