def count_value(a, target):
    start, end = 0, len(a) - 1
    idx = -1
    while start <= end:
        mid = (start + end) // 2
        if a[mid] == target:
            idx = mid
            break
        elif a[mid] > target:
            start = mid + 1
        else:
            end = mid - 1
    if idx == -1:
        return 0
    left = idx
    while left > 0 and a[left-1] == target:
        left -= 1
    right = idx
    while right < len(a) - 1 and a[right+1] == target:
        right += 1
    return right - left + 1

