pr.solution:
def encode(message, X):
    result = ""
    for c in message:
        k = ord(c)
        if c != " ":
            k = k + X
            if k > 90:
                k = k - 26
        result = result + chr(k)
    return result

def save(message, X):
    f = open("encoded_file.txt", "w")
    f.write(encode(message, X))
    f.close()

def decode_file(X):
    f = open("encoded_file.txt", "r")
    m = f.read()
    f.close()
    return encode(m, 26 - X)

